  .folder-dialog{width:min(420px,calc(100vw - 2rem));padding:0;border:0;border-radius:1rem;box-shadow:0 24px 70px rgba(20,37,68,.25)}.folder-dialog::backdrop{background:rgba(18,30,52,.28);backdrop-filter:blur(2px)}.dialog-inner{padding:1.25rem}.dialog-inner h2{margin:0;color:#25334a;font-size:1.08rem;font-weight:800}.dialog-inner p{margin:.3rem 0 1rem;color:#78879c;font-size:.83rem}.dialog-inner .form-control{border-radius:.7rem}.dialog-actions{display:flex;justify-content:flex-end;gap:.55rem;margin-top:1rem}.dialog-actions .btn{border-radius:.68rem;font-weight:700}
