<script>
  const ALL = "__all__";
  const $ = (id) => document.getElementById(id);
  const el = { uploadInput:$("uploadInput"), btnUpload:$("btnUpload"), btnNewFolder:$("btnNewFolder"), btnReload:$("btnReload"), btnBack:$("btnBack"), btnUp:$("btnUp"), content:$("finderContent"), tree:$("folderTree"), folders:$("folderGrid"), grid:$("mediaGrid"), crumbs:$("breadcrumbs"), type:$("typeFilter"), search:$("searchInput"), meta:$("meta"), title:$("viewTitle"), empty:$("empty"), menu:$("contextMenu"), dialog:$("folderDialog"), form:$("folderCreateForm"), folderName:$("folderNameInput"), dialogPath:$("folderDialogPath"), cancelFolder:$("btnCancelFolder"), progress:$("uploadProgress"), progressBar:$("uploadProgressBar"), progressText:$("uploadProgressText"), progressLabel:$("uploadProgressLabel"), selectionToolbar:$("selectionToolbar"), selectionCount:$("selectionCount"), btnSelectAll:$("btnSelectAll"), btnSelectAllQuick:$("btnSelectAllQuick"), btnClearSelection:$("btnClearSelection"), btnDeleteSelected:$("btnDeleteSelected"), marquee:$("selectionMarquee") };
  let files = [], folders = [], totalFiles = 0, folderTotalFiles = 0, folderFileCounts = {}, active = ALL, history = [ALL], historyIndex = 0, dialogParent = "", contextTarget = null, selectedFiles = new Set(), selectedFolders = new Set(), selectionMode = false, loadSequence = 0, lasso = null, suppressCardClick = false;

  const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
  const bytes = (value) => { const n=Number(value||0); return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`; };
  const date = (value) => value ? new Date(Number(value)*1000).toLocaleDateString("vi-VN",{day:"2-digit",month:"2-digit",year:"numeric"}) : "";
  const norm = (value) => String(value||"").replace(/^\/+|\/+$/g,"");
  const allView = (value=active) => value === ALL;
  const parent = (folder) => { const value=norm(folder), i=value.lastIndexOf("/"); return i<0?"":value.slice(0,i); };
  const leaf = (folder) => { const value=norm(folder); return value ? value.split("/").pop() : "Thư viện"; };
  const pretty = (folder) => leaf(folder).replace(/-/g," ");
  const fileName = (file) => { if (file?.name) return String(file.name); try { return decodeURIComponent(String(file?.url||"").split("/").pop()||"file"); } catch (_) { return String(file?.url||"").split("/").pop()||"file"; } };
  const physical = () => allView() ? "" : active;
  async function post(url,payload) { const response=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:payload==null?null:JSON.stringify(payload)}); return {response,data:await response.json().catch(()=>({}))}; }
  function setProgress(percent,label) { const value=Math.max(0,Math.min(100,Math.round(Number(percent||0)))); el.progress.classList.add("show");el.progressBar.style.width=`${value}%`;el.progressText.textContent=`${value}%`;if(label)el.progressLabel.textContent=label; }
  function hideProgress(){setTimeout(()=>{el.progress.classList.remove("show");el.progressBar.style.width="0%";el.progressText.textContent="0%";el.progressLabel.textContent="Đang tải lên...";},700);}
  function selectedTotal(){return selectedFiles.size+selectedFolders.size;}
  function selectionLabel(){const parts=[];if(selectedFiles.size)parts.push(`${selectedFiles.size} file`);if(selectedFolders.size)parts.push(`${selectedFolders.size} folder`);return parts.join(" · ")||"0 mục";}
  function syncSelectionUi(){const total=selectedTotal();el.content.classList.toggle("is-selection-mode",selectionMode);el.selectionToolbar.hidden=total===0;el.selectionCount.textContent=`${selectionLabel()} đã chọn`;el.btnDeleteSelected.disabled=total===0;document.querySelectorAll(".selectable[data-select-kind]").forEach((node)=>{const kind=node.dataset.selectKind||"",id=kind==="folder"?String(node.dataset.folder||""):String(node.dataset.url||""),isSelected=kind==="folder"?selectedFolders.has(id):selectedFiles.has(id);node.classList.toggle("is-selected",isSelected);node.setAttribute("aria-selected",isSelected?"true":"false");const toggle=node.querySelector("[data-selection-toggle]");if(toggle){toggle.hidden=!selectionMode;toggle.tabIndex=selectionMode?0:-1;toggle.setAttribute("aria-pressed",isSelected?"true":"false");toggle.innerHTML=`<i class="fa-solid ${isSelected?"fa-check":"fa-plus"}"></i>`;}});}
  function clearSelection(sync=true,resetMode=true){selectedFiles.clear();selectedFolders.clear();if(resetMode)selectionMode=false;if(sync)syncSelectionUi();}
  function setSelection(kind,id,additive=false){const value=String(id||"");if(!value)return;if(!additive)clearSelection(false,false);const group=kind==="folder"?selectedFolders:selectedFiles;group.add(value);syncSelectionUi();}
  function toggleSelection(kind,id){const value=String(id||"");if(!value)return;const group=kind==="folder"?selectedFolders:selectedFiles;if(group.has(value))group.delete(value);else group.add(value);syncSelectionUi();}
  function setSelectionSets(nextFiles,nextFolders){selectedFiles=new Set(nextFiles);selectedFolders=new Set(nextFolders);syncSelectionUi();}
  function selectAllVisible(){selectionMode=true;setSelectionSets(visibleFiles().map((file)=>String(file.url||"")).filter(Boolean),directFolders().map((folder)=>String(folder||"")).filter(Boolean));}
  function select(folder, save=true) { const next=folder===ALL?ALL:norm(folder); if(next===active)return;clearSelection(false);active=next;if(save){history=history.slice(0,historyIndex+1);history.push(next);historyIndex=history.length-1;}el.title.textContent=allView()?"Tất cả folder":pretty(active);el.meta.textContent="Đang tải nội dung folder...";load(); }
  function directFolders(){const p=allView()?"":active,q=String(el.search.value||"").trim().toLocaleLowerCase("vi");return folders.filter((folder)=>parent(folder)===p&&(!q||pretty(folder).toLocaleLowerCase("vi").includes(q))).sort((a,b)=>a.localeCompare(b,"vi"));}
  function visibleFiles(){if(allView())return [];const q=String(el.search.value||"").trim().toLocaleLowerCase("vi"), type=el.type.value;let list=files.filter((file)=>String(file.folder||"")===active);if(type!=="all")list=list.filter((file)=>file.type===type);if(q)list=list.filter((file)=>`${fileName(file)} ${file.folder||""} ${file.url||""}`.toLocaleLowerCase("vi").includes(q));return list;}
  function renderTree(){const count=(folder)=>Math.max(0,Number(folderFileCounts[folder]||0));let html=`<button class="tree-item ${allView()?"active":""}" data-folder="${ALL}" type="button"><i class="fa-regular fa-folder-open"></i><span class="name">Tất cả folder</span><span class="count">${folders.length}</span></button>`;folders.slice().sort((a,b)=>a.localeCompare(b,"vi")).forEach((folder)=>{const depth=Math.max(0,norm(folder).split("/").length-1);html+=`<button class="tree-item ${active===folder?"active":""}" data-folder="${esc(folder)}" type="button" style="padding-left:${.6+depth*.8}rem"><i class="fa-solid fa-folder"></i><span class="name">${esc(pretty(folder))}</span><span class="count">${count(folder)}</span></button>`;});el.tree.innerHTML=html;}
  function renderCrumbs(){const chunks=allView()?[]:active.split("/");let html=`<button class="crumb ${chunks.length===0?"current":""}" type="button" data-folder="${ALL}"><i class="fa-regular fa-hard-drive me-1"></i>Thư viện</button>`, path="";chunks.forEach((chunk,index)=>{path+=(path?"/":"")+chunk;html+=`<span class="sep"><i class="fa-solid fa-chevron-right"></i></span><button class="crumb ${index===chunks.length-1?"current":""}" type="button" data-folder="${esc(path)}">${esc(pretty(chunk))}</button>`;});el.crumbs.innerHTML=html;}
  function renderFolders(){el.folders.innerHTML=directFolders().map((folder)=>{const directFiles=Math.max(0,Number(folderFileCounts[folder]||0)),children=folders.filter((candidate)=>parent(candidate)===folder).length,isSelected=selectedFolders.has(folder),toggleState=selectionMode?"":" hidden",toggleTabIndex=selectionMode?0:-1;return `<article class="folder-card selectable ${isSelected?"is-selected":""}" tabindex="0" role="button" aria-selected="${isSelected?"true":"false"}" data-folder="${esc(folder)}" data-select-kind="folder"><button class="selection-toggle" type="button" data-selection-toggle${toggleState} tabindex="${toggleTabIndex}" aria-label="Chọn folder ${esc(pretty(folder))}" aria-pressed="${isSelected?"true":"false"}"><i class="fa-solid ${isSelected?"fa-check":"fa-plus"}"></i></button><i class="fa-solid fa-folder"></i><span><strong>${esc(pretty(folder))}</strong><small>${directFiles} file${children?` · ${children} folder`:""}</small></span></article>`;}).join("");}
  function renderFiles(){const list=visibleFiles();el.grid.innerHTML=list.map((file)=>{const rawUrl=String(file.url||""),url=esc(rawUrl),name=esc(fileName(file)),type=file.type==="video"?"MP4":String(file.ext||"JPG").toUpperCase(),isSelected=selectedFiles.has(rawUrl),toggleState=selectionMode?"":" hidden",toggleTabIndex=selectionMode?0:-1,preview=file.type==="image"?`<img src="${url}" alt="" loading="lazy">`:`<span class="video-preview"><i class="fa-solid fa-film fa-2x"></i></span>`;return `<article class="media-card selectable ${isSelected?"is-selected":""}" tabindex="0" aria-selected="${isSelected?"true":"false"}" data-url="${url}" data-select-kind="file"><button class="selection-toggle" type="button" data-selection-toggle${toggleState} tabindex="${toggleTabIndex}" aria-label="Chọn file ${name}" aria-pressed="${isSelected?"true":"false"}"><i class="fa-solid ${isSelected?"fa-check":"fa-plus"}"></i></button><div class="media-preview">${preview}<span class="media-type">${esc(type)}</span></div><div class="media-info"><span class="media-name" title="${name}">${name}</span><span class="media-detail"><span>${bytes(file.size)}</span><span>${esc(date(file.mtime))}</span></span></div></article>`;}).join("");el.empty.classList.toggle("d-none",list.length!==0||directFolders().length!==0);}
  function render(){renderTree();renderCrumbs();renderFolders();renderFiles();el.btnBack.disabled=historyIndex<=0;el.btnUp.disabled=allView()||active==="";el.type.disabled=allView();el.title.textContent=allView()?"Tất cả folder":pretty(active);const shown=visibleFiles().length,rootFolders=directFolders().length;el.meta.textContent=allView()?`${rootFolders} folder cấp 1 · ${totalFiles} file trong thư viện · ảnh chỉ tải khi mở folder`:`${shown}${folderTotalFiles>shown?`/${folderTotalFiles}`:""} file trong folder này`;syncSelectionUi();}
  async function load(){const requestId=++loadSequence,requestedFolder=active,payload=allView()?{scope:"folders",root_folders_only:true}:{folder:active};el.meta.textContent="Đang tải nội dung folder...";const {response,data}=await post("/admin/api/media/list.php",payload);if(requestId!==loadSequence||requestedFolder!==active)return;if(!response.ok||!data.ok){window.adminToast("danger",data.message||"Không tải được thư viện.",{icon:"fa-solid fa-triangle-exclamation"});return;}files=Array.isArray(data.files)?data.files:[];folders=Array.from(new Set((Array.isArray(data.folders)?data.folders:[]).map(norm).filter(Boolean)));folderFileCounts=data.folder_file_counts&&typeof data.folder_file_counts==="object"&&!Array.isArray(data.folder_file_counts)?data.folder_file_counts:{};totalFiles=Number(data.total_files??files.length);folderTotalFiles=Number(data.folder_total_files??files.length);if(!allView()&&!folders.includes(active)){active=ALL;clearSelection(false);load();return;}clearSelection(false);render();}
  function showFolderDialog(folder=physical()){dialogParent=norm(folder);el.dialogPath.textContent=dialogParent?`Trong ${dialogParent}`:"Trong Thư viện";el.folderName.value="";if(typeof el.dialog.showModal==="function")el.dialog.showModal();else{const name=window.prompt(`Tạo folder trong ${dialogParent||"Thư viện"}:`);if(name)createFolder(name,dialogParent);}setTimeout(()=>el.folderName.focus(),0);}
  async function createFolder(name,parentFolder=dialogParent){const value=String(name||"").trim();if(!value)return;const {response,data}=await post("/admin/api/media/folder-create.php",{name:value,parent:norm(parentFolder)});if(!response.ok||!data.ok){window.adminToast("danger",data.message||"Không tạo được folder.",{icon:"fa-solid fa-triangle-exclamation"});return;}const folder=String(data.folder||"");window.adminToast("success",data.message||"Đã tạo folder.",{icon:"fa-solid fa-folder-plus"});await load();if(folder)select(folder);}
  async function copy(value){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);return true;}}catch(_){}const area=document.createElement("textarea");area.value=value;area.style.cssText="position:fixed;left:-9999px";document.body.appendChild(area);area.select();const done=document.execCommand("copy");area.remove();return done;}
  async function upload(input){const queue=Array.from(input||[]).filter(Boolean);if(!queue.length)return;el.btnUpload.disabled=true;let uploaded=0,compressed=0,warnings=[];try{for(let i=0;i<queue.length;i+=1){const file=queue[i];setProgress(0,`Đang tải ${i+1}/${queue.length}: ${file.name}`);const {res,data}=await window.adminUploadFile(file,{folder:physical(),onProgress:(percent)=>setProgress(percent,percent>=100?`Đang xử lý và nén ${i+1}/${queue.length}: ${file.name}`:`Đang tải ${i+1}/${queue.length}: ${file.name}`)});if(!res.ok||!data.ok){window.adminToast("danger",`${file.name}: ${data.message||"Upload thất bại."}`,{icon:"fa-solid fa-triangle-exclamation"});continue;}uploaded+=1;const compression=data.file?.compression||{};if(compression.ok){compressed+=1;const oldSize=Number(compression.old_size||0),newSize=Number(compression.new_size||0);setProgress(100,`Đã nén ${i+1}/${queue.length}: ${file.name}${oldSize&&newSize?` (${bytes(oldSize)} → ${bytes(newSize)})`:""}`);}else{setProgress(100,`Đã tải ${i+1}/${queue.length}: ${file.name}`);}if(compression.warning)warnings.push(`${file.name}: ${compression.warning}`);}if(uploaded){window.adminToast("success",`Đã upload ${uploaded}/${queue.length} file${compressed?` · ${compressed} ảnh đã tự nén`:""}.`,{icon:"fa-solid fa-circle-check"});}if(warnings.length){window.adminToast("warning",warnings[0]+(warnings.length>1?` (+${warnings.length-1} ảnh khác)`:""),{icon:"fa-solid fa-triangle-exclamation"});}await load();}finally{el.btnUpload.disabled=false;hideProgress();}}
  async function compress(url){if(!window.confirm("Nén ảnh này thành JPG dưới 200 KB? Ảnh JPG sẽ bị ghi đè."))return;const {response,data}=await post("/admin/api/media/compress.php",{url});if(!response.ok||!data.ok){window.adminToast("danger",data.message||"Nén ảnh thất bại.",{icon:"fa-solid fa-triangle-exclamation"});return;}const file=data.file||{};window.adminToast("success",`Đã nén: ${bytes(file.old_size)} → ${bytes(file.new_size)}`,{icon:"fa-solid fa-circle-check"});if(file.url&&file.source_url&&file.url!==file.source_url){await copy(file.url);window.adminToast("info","Đã copy URL JPG mới.",{icon:"fa-solid fa-copy"});}await load();}
  async function remove(url){if(!window.confirm("Xoá file này? Hành động này không thể hoàn tác."))return;const {response,data}=await post("/admin/api/media/delete.php",{url});if(!response.ok||!data.ok){window.adminToast("danger",data.message||"Xoá file thất bại.",{icon:"fa-solid fa-triangle-exclamation"});return;}window.adminToast("success",data.message||"Đã xoá file.",{icon:"fa-solid fa-trash-can"});await load();}
  async function removeFolder(folder){const value=norm(folder);if(!value)return;const name=pretty(value);if(!window.confirm(`Xoá folder “${name}”?\n\nFolder trống sẽ được xoá ngay. Nếu còn nội dung, hệ thống sẽ hiển thị chi tiết để bạn xác nhận thêm một lần.`))return;let result=await post("/admin/api/media/folder-delete.php",{folder:value});if(!result.response.ok&&result.data?.code==="folder_not_empty"){const counts=result.data.counts||{},files=Number(counts.files||0),folders=Number(counts.folders||0),size=bytes(counts.bytes||0),typed=window.prompt(`Folder “${name}” có ${files} file, ${folders} folder con (${size}).\n\nẢnh đang được cơ sở, bác sĩ hoặc bài viết sử dụng có thể không hiển thị sau khi xoá.\n\nGõ XOA để xoá vĩnh viễn toàn bộ nội dung:`);if(String(typed||"").trim().toUpperCase()!=="XOA"){window.adminToast("info","Đã giữ nguyên folder và nội dung.",{icon:"fa-solid fa-folder"});return;}result=await post("/admin/api/media/folder-delete.php",{folder:value,recursive:true,confirmation:"DELETE_FOLDER_CONTENTS"});}const {response,data}=result;if(!response.ok||!data.ok){window.adminToast("danger",data.message||"Không xoá được folder.",{icon:"fa-solid fa-triangle-exclamation"});return;}const leavingDeletedFolder=active===value||active.startsWith(`${value}/`);window.adminToast("success",data.message||"Đã xoá folder.",{icon:"fa-solid fa-folder-minus"});if(leavingDeletedFolder){select(parent(value)||ALL);return;}await load();}
  function selectedItems(){return [...Array.from(selectedFiles).map((url)=>({kind:"file",url})),...Array.from(selectedFolders).map((folder)=>({kind:"folder",folder}))];}
  async function deleteSelected(){const items=selectedItems();if(!items.length)return;const preview=await post("/admin/api/media/bulk-delete.php",{items,preview:true});if(!preview.response.ok||!preview.data.ok){window.adminToast("danger",preview.data.message||"Không kiểm tra được các mục đã chọn.",{icon:"fa-solid fa-triangle-exclamation"});return;}const stats=preview.data.stats||{},fileCount=Number(stats.files||0),folderCount=Number(stats.folders||0),size=bytes(stats.bytes||0),selection=preview.data.selection||{},ignored=Number(selection.ignored_descendants||0),detail=`${fileCount} file, ${folderCount} folder (${size})`;if(!window.confirm(`Xoá vĩnh viễn ${detail}?\n\nẢnh đang được cơ sở, bác sĩ hoặc bài viết sử dụng có thể không hiển thị sau khi xoá.${ignored?`\n\n${ignored} mục con đã được gộp vào folder cha.`:""}`))return;const typed=window.prompt(`Gõ XOA để xác nhận xoá ${detail}:`);if(String(typed||"").trim().toUpperCase()!=="XOA"){window.adminToast("info","Đã giữ nguyên các mục đã chọn.",{icon:"fa-solid fa-folder"});return;}const result=await post("/admin/api/media/bulk-delete.php",{items,confirmation:"DELETE_SELECTED_ITEMS"});if(!result.response.ok||!result.data.ok){window.adminToast("danger",result.data.message||"Xoá hàng loạt chưa hoàn tất. Thư viện sẽ được tải lại để kiểm tra.",{icon:"fa-solid fa-triangle-exclamation"});clearSelection(false);await load();return;}const deleted=result.data.deleted||{};window.adminToast("success",`Đã xoá ${Number(deleted.files||0)} file và ${Number(deleted.folders||0)} folder.`,{icon:"fa-solid fa-trash-can"});clearSelection(false);await load();}
  function hideMenu(){el.menu.hidden=true;contextTarget=null;}
  function menu(event,target){event.preventDefault();contextTarget=target;const hasMultiple=selectedTotal()>1,bulkAction=hasMultiple?[["sep"],["delete-selected","fa-trash-can",`Xoá ${selectionLabel()} đã chọn`,"danger"]]:[],actions=target.kind==="file"?[["preview","fa-arrow-up-right-from-square",target.file.type==="image"?"Xem ảnh":"Mở file"],["copy","fa-copy","Copy URL"],...(target.file.type==="image"?[["compress","fa-compress","Nén ảnh (<200 KB)"]]:[]),["sep"],["delete","fa-trash-can","Xoá file","danger"],...bulkAction]:[["open","fa-folder-open",target.folder===ALL?"Mở tất cả file":"Mở folder"],["new","fa-folder-plus","Tạo folder mới tại đây"],["copy-folder","fa-copy","Copy đường dẫn folder"],...(target.folder===ALL?[]:[["sep"],["delete-folder","fa-folder-minus","Xoá folder…","danger"]]),...bulkAction];el.menu.innerHTML=actions.map((action)=>action[0]==="sep"?'<div class="context-sep"></div>':`<button class="context-action ${action[3]||""}" type="button" data-action="${action[0]}"><i class="fa-solid ${action[1]}"></i>${action[2]}</button>`).join("");el.menu.hidden=false;el.menu.style.left=`${Math.max(8,Math.min(event.clientX,window.innerWidth-el.menu.offsetWidth-10))}px`;el.menu.style.top=`${Math.max(8,Math.min(event.clientY,window.innerHeight-el.menu.offsetHeight-10))}px`;}
  function cardData(card){if(!card)return null;const kind=String(card.dataset.selectKind||"");const id=kind==="folder"?String(card.dataset.folder||""):String(card.dataset.url||"");return (kind==="folder"||kind==="file")&&id?{kind,id}:null;}
  function toggleCard(card){const data=cardData(card);if(data)toggleSelection(data.kind,data.id);}
  function selectCard(card){const data=cardData(card);if(!data)return;selectionMode=true;toggleSelection(data.kind,data.id);}
  function openCard(card){const data=cardData(card);if(!data)return;if(data.kind==="folder")select(data.id);else window.open(data.id,"_blank","noopener");}
  function isTextEntry(node){return !!node?.closest?.("input,textarea,select,[contenteditable='true']");}
  function updateLasso(event){if(!lasso||event.pointerId!==lasso.pointerId)return;const x=Math.min(lasso.startX,event.clientX),y=Math.min(lasso.startY,event.clientY),width=Math.abs(event.clientX-lasso.startX),height=Math.abs(event.clientY-lasso.startY);if(!lasso.moved&&width<5&&height<5)return;lasso.moved=true;el.marquee.hidden=false;el.marquee.style.left=`${x}px`;el.marquee.style.top=`${y}px`;el.marquee.style.width=`${width}px`;el.marquee.style.height=`${height}px`;const nextFiles=lasso.additive?new Set(lasso.baseFiles):new Set(),nextFolders=lasso.additive?new Set(lasso.baseFolders):new Set(),right=x+width,bottom=y+height;document.querySelectorAll(".selectable[data-select-kind]").forEach((card)=>{const rect=card.getBoundingClientRect();if(rect.right>=x&&rect.left<=right&&rect.bottom>=y&&rect.top<=bottom){const data=cardData(card);if(!data)return;if(data.kind==="folder")nextFolders.add(data.id);else nextFiles.add(data.id);}});setSelectionSets(nextFiles,nextFolders);}
  function endLasso(event){if(!lasso||event.pointerId!==lasso.pointerId)return;const moved=lasso.moved;try{if(el.content.hasPointerCapture?.(event.pointerId))el.content.releasePointerCapture(event.pointerId);}catch(_){}lasso=null;el.marquee.hidden=true;el.content.classList.remove("is-selecting");if(moved){suppressCardClick=true;setTimeout(()=>{suppressCardClick=false;},0);}}
  function startLasso(event){if(event.pointerType==="touch"||event.button!==0||event.target.closest(".selectable,button,input,textarea,select,a,label")||!event.target.closest("#folderGrid,#mediaGrid"))return;selectionMode=true;if(!(event.metaKey||event.ctrlKey))clearSelection(false,false);syncSelectionUi();lasso={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,baseFiles:new Set(selectedFiles),baseFolders:new Set(selectedFolders),additive:Boolean(event.metaKey||event.ctrlKey),moved:false};try{el.content.setPointerCapture(event.pointerId);}catch(_){}el.content.classList.add("is-selecting");}
  function bindCardGrid(container){container.addEventListener("click",(event)=>{if(suppressCardClick)return;const card=event.target.closest(".selectable[data-select-kind]");if(!card||!container.contains(card))return;if(event.target.closest("[data-selection-toggle]")){event.preventDefault();event.stopPropagation();selectionMode=true;toggleCard(card);return;}if(event.metaKey||event.ctrlKey){event.preventDefault();selectCard(card);return;}openCard(card);});container.addEventListener("keydown",(event)=>{const card=event.target.closest(".selectable[data-select-kind]");if(!card||!container.contains(card))return;if(event.key===" "){event.preventDefault();selectionMode=true;toggleCard(card);return;}if(event.key==="Enter"){event.preventDefault();openCard(card);}});}
  bindCardGrid(el.folders);bindCardGrid(el.grid);
  el.tree.addEventListener("click",(event)=>{const button=event.target.closest("[data-folder]");if(button)select(button.dataset.folder||ALL);});el.crumbs.addEventListener("click",(event)=>{const button=event.target.closest("[data-folder]");if(button)select(button.dataset.folder||ALL);});
  document.addEventListener("contextmenu",(event)=>{const selectable=event.target.closest(".selectable[data-select-kind]");if(selectable){const data=cardData(selectable);if(data){const group=data.kind==="folder"?selectedFolders:selectedFiles;if(!group.has(data.id))setSelection(data.kind,data.id);if(data.kind==="file"){const file=files.find((item)=>String(item.url||"")===data.id);if(file)menu(event,{kind:"file",file});return;}menu(event,{kind:"folder",folder:data.id});return;}}const folder=event.target.closest("[data-folder]");if(folder&&(folder.closest("#folderTree")||folder.closest("#folderGrid"))){menu(event,{kind:"folder",folder:folder.dataset.folder||ALL});return;}if(event.target.closest("#finderContent")||event.target.closest("#finderSide"))menu(event,{kind:"folder",folder:physical()||ALL});});document.addEventListener("click",(event)=>{if(!el.menu.hidden&&!event.target.closest("#contextMenu"))hideMenu();});document.addEventListener("keydown",(event)=>{if(event.key==="Escape"){if(selectedTotal())clearSelection();hideMenu();return;}if(isTextEntry(event.target))return;const isMeta=event.metaKey||event.ctrlKey;if(isMeta&&event.key.toLowerCase()==="a"){event.preventDefault();selectAllVisible();return;}if((event.key==="Delete"||event.key==="Backspace")&&selectedTotal()){event.preventDefault();deleteSelected();}});
  el.menu.addEventListener("click",async(event)=>{const action=event.target.closest("[data-action]")?.dataset.action,target=contextTarget;hideMenu();if(!action||!target)return;if(action==="delete-selected"){await deleteSelected();return;}if(target.kind==="folder"){if(action==="open")select(target.folder||ALL);if(action==="new")showFolderDialog(target.folder===ALL?"":target.folder);if(action==="copy-folder"&&await copy(target.folder===ALL?"/uploads/library":`/uploads/library/${target.folder}`))window.adminToast("success","Đã copy đường dẫn folder.",{icon:"fa-solid fa-copy"});if(action==="delete-folder")await removeFolder(target.folder);return;}if(action==="preview")window.open(target.file.url,"_blank","noopener");if(action==="copy"&&await copy(target.file.url))window.adminToast("success","Đã copy URL file.",{icon:"fa-solid fa-copy"});if(action==="compress")await compress(target.file.url);if(action==="delete")await remove(target.file.url);});
  el.btnUpload.addEventListener("click",()=>el.uploadInput.click());el.btnNewFolder.addEventListener("click",()=>showFolderDialog());el.btnReload.addEventListener("click",load);el.btnBack.addEventListener("click",()=>{if(historyIndex>0){historyIndex-=1;select(history[historyIndex],false);}});el.btnUp.addEventListener("click",()=>{if(!allView())select(parent(active)||ALL);});el.type.addEventListener("change",()=>{clearSelection(false);render();});el.search.addEventListener("input",()=>{clearSelection(false);render();});el.btnSelectAll.addEventListener("click",selectAllVisible);el.btnSelectAllQuick.addEventListener("click",selectAllVisible);el.btnClearSelection.addEventListener("click",()=>clearSelection());el.btnDeleteSelected.addEventListener("click",deleteSelected);el.content.addEventListener("pointerdown",startLasso);el.content.addEventListener("pointermove",updateLasso);el.content.addEventListener("pointerup",endLasso);el.content.addEventListener("pointercancel",endLasso);el.uploadInput.addEventListener("change",async()=>{const input=el.uploadInput.files;el.uploadInput.value="";await upload(input);});el.content.addEventListener("dragover",(event)=>{event.preventDefault();el.content.classList.add("dragging");});el.content.addEventListener("dragleave",(event)=>{if(!el.content.contains(event.relatedTarget))el.content.classList.remove("dragging");});el.content.addEventListener("drop",async(event)=>{event.preventDefault();el.content.classList.remove("dragging");await upload(event.dataTransfer?.files);});el.form.addEventListener("submit",async(event)=>{event.preventDefault();const name=el.folderName.value;if(typeof el.dialog.close==="function")el.dialog.close();await createFolder(name,dialogParent);});el.cancelFolder.addEventListener("click",()=>el.dialog.close());
  load();
